import sys
from bisect import bisect_right

def toi(s):
    a, b, c, d = s.split('.')
    return ((int(a) * 256 + int(b)) * 256 + int(c)) * 256 + int(d)

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    rs = sorted((toi(data[1 + 2 * i]), toi(data[2 + 2 * i])) for i in range(n))
    starts, ends = [], []
    for lo, hi in rs:
        if ends and lo <= ends[-1] + 1:
            if hi > ends[-1]:
                ends[-1] = hi
        else:
            starts.append(lo)
            ends.append(hi)
    q = int(data[1 + 2 * n])
    out = []
    for k in range(q):
        x = toi(data[2 + 2 * n + k])
        i = bisect_right(starts, x) - 1
        out.append('Yes' if i >= 0 and x <= ends[i] else 'No')
    print('\n'.join(out))

main()

