        return '%d.%d.%d.%d' % (x >> 24, (x >> 16) & 255, (x >> 8) & 255, x & 255)
    def fmt(rs, qs):
        return str(len(rs)) + '\n' + '\n'.join(ip(a) + ' ' + ip(b) for a, b in rs) + '\n' + str(len(qs)) + '\n' + '\n'.join(ip(x) for x in qs)
    def clip(x):
        return max(0, min(M, x))
    tests = []
    tests.append(fmt([(0, 0)], [0, 1]))
    tests.append(fmt([(0, M)], [0, M, 12345]))
    tests.append(fmt([(M, M)], [M - 1, M]))
    base = (10 << 24) | (10 << 16)
    tests.append(fmt([(base + 356, base + 562), (base + 712, base + 1124), ((10 << 24) | (20 << 16) | (200 << 8) | 20, (10 << 24) | (40 << 16) | (10 << 8) | 100)],
                     [(10 << 24) | (20 << 16) | (100 << 8) | 40, base + 868, base + 356, base + 562, base + 563]))
    tests.append(fmt([(0, 10), (5, 256)], [11, 256, 257]))
    tests.append(fmt([(5, 9), (10, 14), (20, 20)], [4, 9, 10, 14, 15, 19, 20, 21]))
    for _ in range(14):
        S = rng.choice([40, 600, 70000])
        b0 = rng.randint(0, M - 2 * S - 10)
        n = rng.randint(1, 5)
        rs = []
        for _ in range(n):
            a = b0 + rng.randint(0, S)
            rs.append((a, clip(a + rng.randint(0, S // 4))))
        qs = []
        for _ in range(rng.randint(1, 7)):
            t = rng.randint(0, 2)
            if t == 0:
                qs.append(b0 + rng.randint(0, S + S // 4))
            else:
                a, b = rng.choice(rs)
                qs.append(clip(rng.choice([a - 1, a, b, b + 1, rng.randint(a, b)])))
        tests.append(fmt(rs, qs))
    def big(n, q, maxlen, spread=M):
        rs = []
        for _ in range(n):
            a = rng.randint(0, spread)
            rs.append((a, clip(a + rng.randint(0, maxlen))))
        qs = []
        for _ in range(q):
            t = rng.randint(0, 3)
            if t <= 1:
                a, b = rng.choice(rs)
                qs.append(rng.randint(a, b))
            elif t == 2:
                a, b = rng.choice(rs)
                qs.append(clip(rng.choice([a - 1, b + 1])))
            else:
                qs.append(rng.randint(0, M))
        return fmt(rs, qs)
    tests.append(big(3000, 3000, 2 ** 20))
    tests.append(big(50000, 50000, 2 ** 16))
    tests.append(big(50000, 50000, 2 ** 28))
    tests.append(big(50000, 50000, 0))
    return tests

